array-sort.declarations:
static int[] top(int[] input, int count) {
    if (count < 0) throw new IllegalArgumentException("Anzahl negativ");
    int[] copy = input.clone();
    Arrays.sort(copy);
    int[] out = new int[Math.min(count, copy.length)];
    for (int i=0; i<out.length; i++) out[i]=copy[copy.length-1-i];
    return out;
}

brackets.declarations:
static boolean valid(String text) {
    var stack = new ArrayDeque<Character>();
    for (char c : text.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') stack.push(c);
        else {
            char open = switch (c) { case ')' -> '('; case ']' -> '['; case '}' -> '{'; default -> 0; };
            if (open == 0 || stack.isEmpty() || stack.pop() != open) return false;
        }
    }
    return stack.isEmpty();
}

two-sum.declarations:
static Optional<int[]> pair(int[] values, int target) {
    var seen = new HashMap<Long,Integer>();
    for (int i=0; i<values.length; i++) {
        Integer old = seen.get((long)target-values[i]);
        if (old != null) return Optional.of(new int[]{old,i});
        seen.putIfAbsent((long)values[i],i);
    }
    return Optional.empty();
}

