bfs.declarations:
static int distance(int[][] graph,int start,int target) {
    Objects.checkIndex(start,graph.length);
    Objects.checkIndex(target,graph.length);
    int[] distances = new int[graph.length];
    Arrays.fill(distances,-1);
    var queue = new ArrayDeque<Integer>();
    queue.add(start); distances[start]=0;
    while (!queue.isEmpty()) {
        int node=queue.remove();
        if (node==target) return distances[node];
        for (int neighbor : graph[node]) {
            Objects.checkIndex(neighbor,graph.length);
            if (distances[neighbor]<0) { distances[neighbor]=distances[node]+1;queue.add(neighbor); }
        }
    }
    return -1;
}

